import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import Swal from "sweetalert2";
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from "../components/ui/tabs";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "../components/ui/dropdown-menu";
import {
  BarChart3,
  Users,
  Briefcase,
  FileText,
  Plus,
  UserPlus,
  Upload,
  Building2,
  LayoutGrid, // ← AGREGAR
} from "lucide-react";
import { DashboardHeader } from "../components/dashboard/DashboardHeader";
import { StatsCards } from "../components/dashboard/StatsCards";
import { RecentProjects } from "../components/dashboard/RecentProjects";
import { ClientCard } from "../components/shared/ClientCard";
import { DocumentCard } from "../components/shared/DocumentCard";
import { Button } from "../components/ui/button";
import { Card, CardContent } from "../components/ui/card"; // ← AGREGAR
import { useAuth } from "../contexts/AuthContext";
import { useDashboardData } from "../hooks/useDashboardData";
import { documentService } from "../services/documentService";
import { InviteUserModal } from "../components/modals/InviteUserModal";

// Modales
import { CreateUserModal } from "../components/modals/CreateUserModal";
import { CreateClientModal } from "../components/modals/CreateClientModal";
import { CreateProjectModal } from "../components/modals/CreateProjectModal";
import { UploadDocumentModal } from "../components/modals/UploadDocumentModal";
import DocumentManager from "../components/documents/DocumentManager";

const DashboardPage = () => {
  const navigate = useNavigate(); // ← AGREGAR
  const { user } = useAuth();
  const { stats, clients, projects, documents, loading, error, refetch } =
    useDashboardData();
  const [activeTab, setActiveTab] = useState("overview");

  // Estados de modales
  const [showUserModal, setShowUserModal] = useState(false);
  const [showClientModal, setShowClientModal] = useState(false);
  const [showProjectModal, setShowProjectModal] = useState(false);
  const [showDocumentModal, setShowDocumentModal] = useState(false);
  const [showInviteModal, setShowInviteModal] = useState(false);

  const handleDownloadDocument = async (document) => {
    try {
      const blob = await documentService.download(document._id);
      const url = window.URL.createObjectURL(blob);
      const a = window.document.createElement("a");
      a.href = url;
      a.download = document.file_name;
      window.document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      window.document.body.removeChild(a);

      Swal.fire({
        icon: "success",
        title: "Descarga Iniciada",
        text: `Descargando ${document.file_name}`,
        confirmButtonColor: "#16a34a",
        timer: 2000,
      });
    } catch (error) {
      Swal.fire({
        icon: "error",
        title: "Error al Descargar",
        text: "No se pudo descargar el documento. Por favor, intenta de nuevo.",
        confirmButtonColor: "#dc2626",
      });
    }
  };

  const handleModalSuccess = () => {
    refetch();
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-green-500"></div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <p className="text-red-600 text-xl mb-4">Error al cargar los datos</p>
          <Button onClick={refetch}>Reintentar</Button>
        </div>
      </div>
    );
  }

  // Definir permisos por rol
  const isSuperAdmin = user?.role === "super_admin";
  const isAdmin = user?.role === "admin";
  const isUser = user?.role === "user";
  const isClient = user?.role === "client";

  // Permisos específicos
  const canCreateUsers = isSuperAdmin || isAdmin;
  const canCreateClients = isSuperAdmin || isAdmin || isUser;
  const canCreateProjects = isSuperAdmin || isAdmin || isUser;
  const canUploadDocuments = isSuperAdmin || isAdmin || isUser;
  const canViewAllClients = isSuperAdmin || isAdmin;

  return (
    <div className="min-h-screen bg-gray-50">
      <DashboardHeader />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 sm:py-8">
        {/* Botones superiores - RESPONSIVE */}
        {!isClient && (
          <div className="mb-4 sm:mb-6">
            {/* Mobile: Menú desplegable */}
            <div className="sm:hidden">
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button className="w-full bg-green-600 hover:bg-green-700">
                    <Plus className="w-4 h-4 mr-2" />
                    Crear Nuevo
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent className="w-56">
                  {canCreateUsers && (
                    <DropdownMenuItem onClick={() => setShowInviteModal(true)}>
                      <UserPlus className="w-4 h-4 mr-2" />
                      Invitar Usuario
                    </DropdownMenuItem>
                  )}
                  {canCreateClients && (
                    <DropdownMenuItem onClick={() => setShowClientModal(true)}>
                      <Building2 className="w-4 h-4 mr-2" />
                      Nuevo Cliente
                    </DropdownMenuItem>
                  )}
                  {canCreateProjects && (
                    <DropdownMenuItem onClick={() => setShowProjectModal(true)}>
                      <Briefcase className="w-4 h-4 mr-2" />
                      Nuevo Proyecto
                    </DropdownMenuItem>
                  )}
                  {canUploadDocuments && (
                    <DropdownMenuItem
                      onClick={() => setShowDocumentModal(true)}
                    >
                      <Upload className="w-4 h-4 mr-2" />
                      Subir Documento
                    </DropdownMenuItem>
                  )}
                </DropdownMenuContent>
              </DropdownMenu>
            </div>

            {/* Desktop: Botones horizontales */}
            <div className="hidden sm:flex justify-end gap-3 flex-wrap">
              {canCreateUsers && (
                <Button
                  onClick={() => setShowInviteModal(true)}
                  className="bg-blue-600 hover:bg-blue-700"
                >
                  <UserPlus className="w-4 h-4 mr-2" />
                  Invitar Usuario
                </Button>
              )}
              {canCreateClients && (
                <Button
                  onClick={() => setShowClientModal(true)}
                  className="bg-green-600 hover:bg-green-700"
                >
                  <Plus className="w-4 h-4 mr-2" />
                  Nuevo Cliente
                </Button>
              )}
              {canCreateProjects && (
                <Button
                  onClick={() => setShowProjectModal(true)}
                  className="bg-purple-600 hover:bg-purple-700"
                >
                  <Plus className="w-4 h-4 mr-2" />
                  Nuevo Proyecto
                </Button>
              )}
              {canUploadDocuments && (
                <Button
                  onClick={() => setShowDocumentModal(true)}
                  className="bg-orange-600 hover:bg-orange-700"
                >
                  <Upload className="w-4 h-4 mr-2" />
                  Subir Documento
                </Button>
              )}
            </div>
          </div>
        )}

        <Tabs value={activeTab} onValueChange={setActiveTab}>
          {/* Tabs List - RESPONSIVE */}
          <TabsList className="grid w-full grid-cols-2 sm:grid-cols-4 mb-4 sm:mb-6">
            <TabsTrigger value="overview" className="text-xs sm:text-sm">
              <BarChart3 className="w-3 h-3 sm:w-4 sm:h-4 mr-1 sm:mr-2" />
              <span className="hidden sm:inline">Resumen</span>
              <span className="sm:hidden">Inicio</span>
            </TabsTrigger>
            <TabsTrigger
              value="clients"
              disabled={isClient}
              className="text-xs sm:text-sm"
            >
              <Users className="w-3 h-3 sm:w-4 sm:h-4 mr-1 sm:mr-2" />
              Clientes
            </TabsTrigger>
            <TabsTrigger value="projects" className="text-xs sm:text-sm">
              <Briefcase className="w-3 h-3 sm:w-4 sm:h-4 mr-1 sm:mr-2" />
              Proyectos
            </TabsTrigger>
            {/* ← NUEVA PESTAÑA */}
            <TabsTrigger value="all-documents" className="text-xs sm:text-sm">
              <FileText className="w-3 h-3 sm:w-4 sm:h-4 mr-1 sm:mr-2" />
              <span className="hidden sm:inline">Todos</span>
              <span className="sm:hidden">📁</span>
            </TabsTrigger>
          </TabsList>

          {/* Overview Tab */}
          <TabsContent value="overview" className="space-y-6">
            <StatsCards stats={stats} userRole={user?.role} />
            <RecentProjects projects={projects} onUpdate={refetch} />
          </TabsContent>

          {/* Clients Tab */}

          <TabsContent value="clients" className="space-y-6">
            <div className="flex justify-between items-center">
              <div>
                <h2 className="text-2xl font-bold text-gray-900">
                  Gestión de Clientes
                </h2>
                {!canViewAllClients && (
                  <p className="text-sm text-gray-600 mt-1">
                    Mostrando solo tus clientes asignados
                  </p>
                )}
              </div>
              {canCreateClients && (
                <Button
                  onClick={() => setShowClientModal(true)}
                  className="bg-green-600 hover:bg-green-700"
                >
                  <Plus className="w-4 h-4 mr-2" />
                  Nuevo Cliente
                </Button>
              )}
            </div>

            <div className="grid gap-6">
              {clients.length === 0 ? (
                <div className="text-center py-12 bg-white rounded-lg">
                  <Users className="w-16 h-16 mx-auto text-gray-400 mb-4" />
                  <p className="text-gray-600">
                    {canViewAllClients
                      ? "No hay clientes registrados"
                      : "No tienes clientes asignados"}
                  </p>
                  {canCreateClients && (
                    <Button
                      onClick={() => setShowClientModal(true)}
                      className="mt-4 bg-green-600 hover:bg-green-700"
                    >
                      Crear Primer Cliente
                    </Button>
                  )}
                </div>
              ) : (
                clients.map((client) => (
                  <ClientCard
                    key={client._id}
                    client={client}
                    onUpdate={refetch} // ← AGREGAR ESTO
                  />
                ))
              )}
            </div>
          </TabsContent>

          {/* Projects Tab - MODIFICADO */}
          <TabsContent value="projects" className="space-y-6">
            <div className="flex justify-between items-center">
              <div>
                <h2 className="text-2xl font-bold text-gray-900">Proyectos</h2>
                <p className="text-sm text-gray-600 mt-1">
                  Vista rápida de tus proyectos recientes
                </p>
              </div>
              <Button
                onClick={() => navigate("/projects")}
                className="bg-green-600 hover:bg-green-700"
              >
                <LayoutGrid className="w-4 h-4 mr-2" />
                Ver Todos los Proyectos
              </Button>
            </div>

            <Card>
              <CardContent className="p-8 text-center">
                <Briefcase className="w-16 h-16 mx-auto text-gray-400 mb-4" />
                <h3 className="text-lg font-semibold text-gray-900 mb-2">
                  Gestión Avanzada de Proyectos
                </h3>
                <p className="text-gray-600 mb-6">
                  Usa nuestra nueva interfaz estilo Asana para gestionar tus
                  proyectos de manera más eficiente con tableros Kanban,
                  cronogramas y más.
                </p>
                <Button
                  onClick={() => navigate("/projects")}
                  className="bg-green-600 hover:bg-green-700"
                >
                  <LayoutGrid className="w-4 h-4 mr-2" />
                  Abrir Gestión de Proyectos
                </Button>
              </CardContent>
            </Card>

            {/* Proyectos Recientes */}
            <RecentProjects
              projects={projects.slice(0, 3)}
              onUpdate={refetch}
            />
          </TabsContent>

          {/* Documents Tab */}
          <TabsContent value="all-documents" className="space-y-4 sm:space-y-6">
            <div className="grid gap-4">
              {documents.length === 0 ? (
                <div className="text-center py-8 sm:py-12 bg-white rounded-lg">
                  <FileText className="w-12 h-12 sm:w-16 sm:h-16 mx-auto text-gray-400 mb-4" />
                  <p className="text-sm sm:text-base text-gray-600">
                    No hay documentos disponibles
                  </p>
                  {canUploadDocuments && (
                    <Button
                      onClick={() => setShowDocumentModal(true)}
                      className="mt-4 bg-green-600 hover:bg-green-700"
                    >
                      Subir Primer Documento
                    </Button>
                  )}
                </div>
              ) : (
                //documents.map((document) => (
                <DocumentManager onUploadSuccess={handleModalSuccess} />
                //<DocumentCard
                //  key={document._id}
                //  document={document}
                //  onDownload={handleDownloadDocument}
                ///>
                //))
              )}
            </div>
          </TabsContent>
        </Tabs>
      </main>

      {/* Modales - Mostrar según permisos */}
      {canCreateUsers && (
        <CreateUserModal
          isOpen={showUserModal}
          onClose={() => setShowUserModal(false)}
          onSuccess={handleModalSuccess}
        />
      )}

      {canCreateClients && (
        <CreateClientModal
          isOpen={showClientModal}
          onClose={() => setShowClientModal(false)}
          onSuccess={handleModalSuccess}
        />
      )}

      {canCreateProjects && (
        <CreateProjectModal
          isOpen={showProjectModal}
          onClose={() => setShowProjectModal(false)}
          onSuccess={handleModalSuccess}
        />
      )}

      <InviteUserModal
        isOpen={showInviteModal}
        onClose={() => setShowInviteModal(false)}
        onSuccess={handleModalSuccess}
      />

      {canUploadDocuments && (
        <UploadDocumentModal
          isOpen={showDocumentModal}
          onClose={() => setShowDocumentModal(false)}
          onSuccess={handleModalSuccess}
        />
      )}
    </div>
  );
};

export default DashboardPage;
